"use client";
// Independently implemented ROC primitive.
export { Shine } from "./motion-effects";
import "./shine.css";

"use client";
import { useRef, useState, type ComponentProps } from "react";
import { motion, useScroll, useTransform } from "motion/react";
import { useRocReducedMotion, useRocTransition } from "./motion-config";
import { cn } from "./utils";
import "./motion-effects.css";

export type EffectKind = "fade" | "slide" | "blur" | "zoom" | "highlight" | "shine" | "click" | "tilt" | "magnetic" | "particles";
export type EffectProps = Omit<ComponentProps<"div">, "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd"> & {
  active?: boolean; effect?: EffectKind; distance?: number;
};
/** Retains the caller's subtree. `active` changes presentation, never presence. */
export function Effect({ active = true, effect = "fade", distance = 18, className, children, ...props }: EffectProps) {
  const reduce = useRocReducedMotion(), transition = useRocTransition();
  const [pointer, setPointer] = useState({ x: 0, y: 0 });
  const moving = !reduce && (effect === "magnetic" || effect === "tilt");
  const point = moving ? pointer : { x: 0, y: 0 };
  const animate = {
    opacity: active || !["fade", "blur", "slide", "zoom"].includes(effect) ? 1 : 0.28,
    x: effect === "magnetic" ? point.x * 0.15 : 0,
    y: !reduce && effect === "slide" && !active ? distance : effect === "magnetic" ? point.y * 0.15 : 0,
    scale: !reduce && ((effect === "zoom" && !active) || (effect === "click" && active)) ? 0.94 : 1,
    rotateX: moving && effect === "tilt" ? -point.y * 0.12 : 0,
    rotateY: moving && effect === "tilt" ? point.x * 0.12 : 0,
    filter: effect === "blur" && !active && !reduce ? "blur(5px)" : "blur(0px)",
    backgroundColor: effect === "highlight" && active ? "var(--roc-marker, #ededed)" : "transparent",
  };
  return <motion.div {...props} className={cn("roc-ui roc-effect", className)} initial={false} animate={animate} transition={transition}
    data-effect={effect} data-active={active} style={{ perspective: 800, ...props.style }}
    onPointerMove={e => {
      props.onPointerMove?.(e);
      if (e.defaultPrevented || !moving || e.pointerType !== "mouse" || !matchMedia("(hover: hover) and (pointer: fine)").matches) return;
      const box = e.currentTarget.getBoundingClientRect();
      setPointer({ x: e.clientX - box.left - box.width / 2, y: e.clientY - box.top - box.height / 2 });
    }} onPointerLeave={e => { props.onPointerLeave?.(e); setPointer({ x: 0, y: 0 }); }}>
    {children}
    {effect === "shine" && <motion.span aria-hidden="true" className="roc-effect-shine" initial={false} animate={{ x: active && !reduce ? "240%" : "-140%" }} transition={{ duration: reduce ? 0 : 0.65 }} />}
    {effect === "particles" && <span aria-hidden="true" className="roc-effect-particles">{Array.from({ length: 10 }, (_, i) => <motion.i key={i} initial={false} animate={{ x: active && !reduce ? [0, Math.cos(i * Math.PI / 5) * 58] : 0, y: active && !reduce ? [0, Math.sin(i * Math.PI / 5) * 40] : 0, opacity: active && !reduce ? [0, 0.8, 0] : 0, scale: active && !reduce ? [0, 1, 0.4] : 0 }} transition={{ type: "tween", duration: reduce ? 0 : 0.65 }} />)}</span>}
  </motion.div>;
}
export function Fade(props: EffectProps) { return <Effect {...props} effect="fade" />; }
export function Slide(props: EffectProps) { return <Effect {...props} effect="slide" />; }
export function Blur(props: EffectProps) { return <Effect {...props} effect="blur" />; }
export function Zoom(props: EffectProps) { return <Effect {...props} effect="zoom" />; }
export function Highlight(props: EffectProps) { return <Effect {...props} effect="highlight" />; }
export function Shine(props: EffectProps) { return <Effect {...props} effect="shine" />; }
export function Click(props: EffectProps) { return <Effect {...props} effect="click" />; }
export function Tilt(props: EffectProps) { return <Effect {...props} effect="tilt" />; }
export function Magnetic(props: EffectProps) { return <Effect {...props} effect="magnetic" />; }
export function Particles(props: EffectProps) { return <Effect {...props} effect="particles" />; }
export function ScrollFade({ children, className, ...props }: ComponentProps<"div">) {
  const target = useRef<HTMLDivElement>(null), reduce = useRocReducedMotion();
  const { scrollYProgress } = useScroll({ target, offset: ["start end", "center center"] });
  const opacity = useTransform(scrollYProgress, [0, 1], [0.25, 1]);
  return <motion.div {...props as object} ref={target} className={cn("roc-ui", className)} style={{ ...props.style, opacity: reduce ? 1 : opacity }}>{children}</motion.div>;
}
export function ImageZoom({ src, alt, className }: { src: string; alt: string; className?: string }) {
  const [zoomed, setZoomed] = useState(false), reduce = useRocReducedMotion(), transition = useRocTransition();
  return <button type="button" className={cn("roc-ui roc-image-zoom", className)} aria-label={`${zoomed ? "Zoom out of" : "Zoom into"} ${alt}`} aria-pressed={zoomed} onClick={() => setZoomed(!zoomed)}>
    <motion.img src={src} alt={alt} initial={false} animate={{ scale: zoomed && !reduce ? 1.6 : 1 }} transition={transition} />
    <span>{zoomed ? "−" : "+"}</span>
  </button>;
}
export function ThemeToggler({ dark, children, className }: ComponentProps<"div"> & { dark: boolean }) {
  const transition = useRocTransition();
  return <motion.div className={cn("roc-ui roc-theme-surface", className)} initial={false} animate={{ backgroundColor: dark ? "#252525" : "#fafafa", color: dark ? "#fafafa" : "#252525" }} transition={transition}>{children}</motion.div>;
}

"use client";
import { type ReactNode } from "react";
import { AnimateUIProvider } from "@animate-ui/react/provider";
import { motionTokens, useShouldReduceMotion, useTempoTransition, type CheckAnimation, type ReducedMotion } from "@animate-ui/react/utils/motion";
import { MotionConfig, type Transition } from "motion/react";

/** ROC's public defaults feed the same provider used by every Animate UI primitive. */
export function RocMotionProvider({ children, pace, reducedMotion, checkAnimation }: {
  children: ReactNode; pace?: number; reducedMotion?: ReducedMotion; checkAnimation?: CheckAnimation;
}) {
  return <AnimateUIProvider tempo={pace === undefined ? undefined : Math.max(0.1, pace)} reducedMotion={reducedMotion} checkAnimation={checkAnimation}>
    <MotionConfig reducedMotion={reducedMotion}>{children}</MotionConfig>
  </AnimateUIProvider>;
}
/** For ROC-only compositions; timings and tempo come from Animate UI. */
export function useRocTransition(kind: "control" | "surface" = "surface"): Transition {
  const transition = useTempoTransition(kind === "control" ? motionTokens.spring.thumb : motionTokens.spring.dialog);
  const reduce = useRocReducedMotion();
  return reduce ? { duration: 0 } : transition;
}
export const useRocReducedMotion = useShouldReduceMotion;

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-effect { position: relative; min-width: 0; border-radius: var(--roc-radius, 12px); }
.roc-effect[data-effect="shine"] { overflow: hidden; }
.roc-effect-shine { position: absolute; inset: 0; width: 45%; pointer-events: none; background: linear-gradient(100deg, transparent, #ffffffb0, transparent); }
.roc-effect-particles { position: absolute; inset: 50%; pointer-events: none; }
.roc-effect-particles i { display: block; position: absolute; width: 4px; height: 4px; border-radius: 50%; background: var(--roc-accent, #777); }
.roc-image-zoom { position: relative; padding: 0; width: 100%; overflow: hidden; border: 1px solid var(--roc-line, #ddd); border-radius: var(--roc-radius, 12px); background: var(--roc-paper, #fff); cursor: zoom-in; }
.roc-image-zoom[aria-pressed="true"] { cursor: zoom-out; }
.roc-image-zoom img { display: block; width: 100%; aspect-ratio: 16 / 9; object-fit: cover; }
.roc-image-zoom > span { position: absolute; bottom: 10px; right: 10px; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; color: #333; background: #fffffff0; }
.roc-theme-surface { padding: 24px; border: 1px solid var(--roc-line, #ddd); border-radius: var(--roc-radius, 12px); }

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-family: var(--roc-font-body, inherit);
  font-size: var(--roc-text-body, 13px);
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}
